INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('tafsir-saadi', 460, '29-05-1448', 'تفسير سورة التوبة: من الآية (٨) ﴿كَيْفَ وَإِنْ يَظْهَرُوا عَلَيْكُمْ لَا يَرْقُبُوا فِيكُمْ إِلًّا وَلَا ذِمَّةً...﴾', 0, 636, 'من قوله: «لعلهم» في قتالكم إياهم «ينتهون» عن الطعن في دينكم، وربما دخلوا فيه.', 638, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/tafsir-assidi/460.mp3', '/detail/MsvrXN0Ry8KL', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('tafsir-saadi', 459, '28-05-1448', 'تفسير سورة التوبة: من الآية (٥) ﴿فَإِذَا انْسَلَخَ الْأَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ...﴾', 0, 635, 'من قوله: ﴿كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ اللَّهِ وَعِندَ رَسُولِهِ﴾', 636, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/tafsir-assidi/459.mp3', '/detail/JhvZ5z2RxyOq', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('tafsir-saadi', 458, '26-05-1448', 'تفسير سورة التوبة: من الآية (١) ﴿بَرَاءَةٌ مِنَ اللَّهِ وَرَسُولِهِ إِلَى الَّذِينَ عَاهَدْتُمْ مِنَ الْمُشْرِكِينَ﴾', 0, 633, 'من قوله: فإذا انسلخ الأشهر الحرم فاقتلوا المشركين حيث وجدتموهم وخذوهم واحصروهم و', 635, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/tafsir-assidi/458.mp3', '/detail/PdCnRxTFHtyV', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('tafsir-saadi', 457, '25-05-1448', 'تفسير سورة الأنفال: من الآية (٧٣) ﴿وَالَّذِينَ كَفَرُوا بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ إِلا تَفْعَلُوهُ تَكُنْ فِتْنَةٌ...﴾', 0, 632, 'من قوله: تم تفسير سورة الأنفال. ولله الحمد والمنة.', 633, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/tafsir-assidi/457.mp3', '/detail/2CJwc5VrnQ1K', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('tafsir-saadi', 456, '24-05-1448', 'تفسير سورة الأنفال: من الآية (٧٠) ﴿يَاأَيُّهَا النَّبِيُّ قُلْ لِمَنْ فِي أَيْدِيكُمْ مِنَ الْأَسْرَى إِنْ يَعْلَمِ...﴾', 0, 631, 'من قوله: يعلم ما أنتم عليه من الأحوال فيشرع لكم من الأحكام ما يليق بكم', 632, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/tafsir-assidi/456.mp3', '/detail/3fGPcQs0DWRt', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('kitab-tawhid', 14, '29-05-1448', 'من قوله: وقال الخليل عليه السلام: ﴿وَاجْنُبْنِي وَبَنِيَّ أَنْ نَعْبُدَ الْأَصْنَامَ﴾', 0, 275, 'من قوله: <فيه مسائل: الأولى: الخوف من الشرك>…', 280, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/taohid/taqrirat-ala-kitab-tauhid/014.mp3', '/detail/w2jUmHdGY9vx', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('kitab-tawhid', 13, '28-05-1448', 'من قوله: باب الخوف من الشرك', 0, 270, 'من قوله: وفيه: أنه يُخاف على البنين كما يُخاف على الأنفس؛ فإذا كان خليل الرحمن…', 275, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/taohid/taqrirat-ala-kitab-tauhid/013.mp3', '/detail/C5brsNEBq1wU', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('kitab-tawhid', 12, '25-05-1448', 'من قوله: فيه مسائل: الأولى: معرفة مراتب الناس في التوحيد', 0, 261, 'من قوله: باب الخوف من الشرك (أي: وجوب الخوف من الشرك وتحتمه والتحذير منه)…', 270, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/taohid/taqrirat-ala-kitab-tauhid/012.mp3', '/detail/P2x9vyOqfMDg', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('kitab-tawhid', 11, '24-05-1448', 'من قوله: عن حصين بن عبد الرحمن قال: كنت عند سعيد بن جبير، فقال: أيكم رأى الكوكب الذي انقض البارحة؟', 0, 254, 'من قوله: فيه مسائل: الأولى: معرفة مراتب الناس في التوحيد…', 261, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/taohid/taqrirat-ala-kitab-tauhid/011.mp3', '/detail/gVDy4fzs5Fwn', '2026-11-10T00:00:00Z');
INSERT OR IGNORE INTO lessons (course_id, number, hijri_date, start_point, pdf_index, start_page, end_point, end_page, end_pdf_index, recording_url, detail_path, created_at) VALUES ('kitab-tawhid', 10, '23-05-1448', 'باب من حقق التوحيد دخل الجنة بغير حساب', 0, 245, 'من قوله: وقد عرفت في تعريف تحقيقه أنه: تخليصه وتصفيته من شوائب الشرك والبدع والم', 254, 0, 'https://media.sualruhailymubasher.com/download/esound/choroohat/taohid/taqrirat-ala-kitab-tauhid/010.mp3', '/detail/aRC2SAZhFLkJ', '2026-11-10T00:00:00Z');
